/**
 * The Album an import is created for from a Web Album page (POST /imports `targetAlbumId`) and the create page's read of that
 * Album (GET /imports/album-targets/:albumId). Creation checks the target as an append's approval does: a ready Album that can
 * be a candidate, whose primary Artist Credits name only ready Artists, with at most ADMIN_IMPORT_LIMITS.appendTargetMembers
 * members, read with the candidate projection so the stored reuse decision binds the revision every later check compares. Owner rules live in docs/business-rules.md
 * (Administrator Album Imports).
 */
import { ObjectId, type ClientSession } from 'mongodb';
import { getDb } from '../../infrastructure/database';
import { legacyAlbumArtistIdsFromCredits, normalizeStoredCatalogCredits } from '../../models/catalogCredit';
import { readyArtistLifecycleFilter } from '../../services/catalog/artistReferenceFenceService';
import { expectedTrackRows, storedExpectedTracklist } from '../../services/catalog/albumExpectedTracklist';
import { adminCatalogArtworkSource } from '../catalog/adminCatalogArtworkSource';
import { ADMIN_IMPORT_LIMITS, cleanText, objectId } from './adminImportContract';
import type { ImportDecisionV2 } from './adminImportDraft';
import { IMPORT_CANDIDATE_COLLECTIONS, importCandidateProjection, importCandidateRow, readyImportCandidate } from './adminImportIdentity';

/**
 * Why files cannot be added to an Album: not a ready Album, a ready Album whose saved title or visibility cannot be read, no
 * primary Artist Credit, a primary Artist that is not ready, or too many members.
 */
export type ImportAlbumTargetRefusal = 'unavailable' | 'unreadable' | 'primaryRequired' | 'primaryNotReady' | 'tooLarge';
/**
 * The 409 code a create names for each refusal; APPEND_PRIMARY_REQUIRED and TARGET_TOO_LARGE are the codes approval and commit
 * already use for an append.
 */
export const IMPORT_ALBUM_TARGET_CODES: Readonly<Record<ImportAlbumTargetRefusal, string>> = {
    unavailable: 'ADMIN_IMPORT_TARGET_UNAVAILABLE', unreadable: 'ADMIN_IMPORT_TARGET_UNAVAILABLE', primaryRequired: 'ADMIN_IMPORT_APPEND_PRIMARY_REQUIRED',
    primaryNotReady: 'ADMIN_IMPORT_TARGET_UNAVAILABLE', tooLarge: 'ADMIN_IMPORT_TARGET_TOO_LARGE'
};
/** Cleaned text, or '' when it is not a clean string of at most `max` characters. */
const shownText = (value: unknown, max: number) => { try { return cleanText(value, max, true); } catch { return ''; } };
/** The ordered primary Artist IDs of stored Album Credits, or null when the stored list cannot be read. */
export const importAlbumPrimaryIds = (credits: unknown): string[] | null => { try { return legacyAlbumArtistIdsFromCredits(normalizeStoredCatalogCredits(credits)); } catch { return null; } };
/** Whether an import was created for an Album (`createdForAlbumId`, AdminImportDocument). */
export const importCreatedForAlbum = (doc: { createdForAlbumId?: unknown }): boolean => objectId(doc.createdForAlbumId);
/** The ready Album `albumId`, read with the candidate projection so its revision is the one Album decisions bind. */
export const readImportAlbumTarget = (albumId: string, session: ClientSession, extra: Record<string, 1> = {}) =>
    getDb()!.collection(IMPORT_CANDIDATE_COLLECTIONS.album).findOne({ _id: new ObjectId(albumId), ...readyImportCandidate('album') },
        { session, projection: { ...importCandidateProjection, ...extra }, maxTimeMS: 3_000 });
/**
 * The Album decision a create for `album` stores: reuse at its current candidate revision, shaped as parseImportDecisions stores
 * one. Throws invalid input for an unclean stored title or a malformed stored visibility (importCandidateRow).
 */
export const importAlbumTargetDecision = (album: Record<string, any>): ImportDecisionV2 => ({
    scope: 'album', slotId: null, action: 'reuse', candidateId: album._id.toHexString(), candidateRevision: importCandidateRow('album', album).revision, entryKey: null, boundName: null
});
/**
 * Reads `albumId` as an import for it would append to it, with the checks approval makes for an append: a ready Album that can
 * be a candidate, whose stored primary Artist Credits name only ready Artists (freezeImportIdentities), within the append member
 * bound. Returns the Album row (null when not a ready Album), the reuse decision a create stores (null when refused) and the
 * refusal, if any.
 */
export async function readImportAlbumTargetState(albumId: string, session: ClientSession, extra: Record<string, 1> = {}): Promise<{
    album: Record<string, any> | null; decision: ImportDecisionV2 | null; refusal: ImportAlbumTargetRefusal | null; primaries: string[] }> {
    const album = await readImportAlbumTarget(albumId, session, extra);
    if (!album) return { album: null, decision: null, refusal: 'unavailable', primaries: [] };
    let decision: ImportDecisionV2;
    try { decision = importAlbumTargetDecision(album); } catch { return { album, decision: null, refusal: 'unreadable', primaries: [] }; }
    const primaries = importAlbumPrimaryIds(album.credits) ?? [];
    if (!primaries.length) return { album, decision: null, refusal: 'primaryRequired', primaries };
    const ready = primaries.every(objectId) ? await getDb()!.collection('artists').countDocuments({ _id: { $in: primaries.map(id => new ObjectId(id)) }, ...readyArtistLifecycleFilter },
        { session, maxTimeMS: 3_000 }) : -1;
    if (ready !== primaries.length) return { album, decision: null, refusal: 'primaryNotReady', primaries };
    if (!Array.isArray(album.audioTrackIds) || album.audioTrackIds.length > ADMIN_IMPORT_LIMITS.appendTargetMembers) return { album, decision: null, refusal: 'tooLarge', primaries };
    return { album, decision, refusal: null, primaries };
}
/**
 * The Disc and Track Numbers of an Album's declared members of any lifecycle state, at most the append member bound. Member IDs
 * are read as the Album page and listener reads normalize them (trimmed, lower case, first occurrence kept); a malformed or
 * dangling one is left out.
 */
export async function importAlbumMemberPositions(audioTrackIds: readonly unknown[], session: ClientSession): Promise<{ id: string; discNumber: unknown; trackNumber: unknown }[]> {
    const bound = ADMIN_IMPORT_LIMITS.appendTargetMembers;
    const ids = [...new Set(audioTrackIds.flatMap(value => { const id = String(value ?? '').trim().toLowerCase(); return objectId(id) ? [id] : []; }))];
    const members = ids.length ? await getDb()!.collection('audioTracks').find({ _id: { $in: ids.map(value => new ObjectId(value)) } }, { session, projection: { discNumber: 1, trackNumber: 1 }, maxTimeMS: 3_000 })
        .limit(bound).toArray() : [];
    return members.map(member => ({ id: member._id.toHexString(), discNumber: member.discNumber, trackNumber: member.trackNumber }));
}

export type ImportAlbumTargetView = {
    albumId: string;
    /** Why files cannot be added to this Album, or null. */
    refusal: ImportAlbumTargetRefusal | null;
    /** Null exactly when `refusal` is `unavailable` or `unreadable`. */
    album: {
        /** The saved title, cleaned. */
        title: string;
        /** The ready primary Artists' names in credit order, at most 50, each cleaned (an unclean name is left out). */
        primaryArtists: string[];
        coverUrl: string | null;
        /** Rows of a valid stored expected tracklist that no declared member fills; null without one or over the member bound. */
        missingRows: number | null;
    } | null;
};
/** The create page's read of `albumId`: its refusal, if any, and what the target card shows. */
export async function importAlbumTargetView(albumId: string, session: ClientSession): Promise<ImportAlbumTargetView> {
    const { album, refusal, primaries: all } = await readImportAlbumTargetState(albumId, session, { expectedTracklist: 1 });
    if (!album || refusal === 'unreadable') return { albumId, refusal, album: null };
    const primaries = all.filter(objectId).slice(0, 50);
    const artists = primaries.length ? await getDb()!.collection('artists').find({ _id: { $in: primaries.map(id => new ObjectId(id)) }, ...readyArtistLifecycleFilter },
        { session, projection: { name: 1 }, maxTimeMS: 3_000 }).limit(50).toArray() : [];
    const names = new Map(artists.map(artist => [artist._id.toHexString(), shownText(artist.name, 200)]));
    const tracklist = storedExpectedTracklist({ expectedTracklist: album.expectedTracklist });
    const missingRows = tracklist && refusal !== 'tooLarge' && Array.isArray(album.audioTrackIds)
        ? expectedTrackRows(tracklist.rows, await importAlbumMemberPositions(album.audioTrackIds, session)).rows.filter(row => !row.memberIds.length).length : null;
    return { albumId, refusal, album: {
        title: shownText(album.title, 300),
        primaryArtists: primaries.map(id => names.get(id) ?? '').filter(Boolean),
        coverUrl: adminCatalogArtworkSource(album) ? `/api/admin/v1/catalog/album/${albumId}/artwork` : null,
        missingRows
    } };
}
